				<div class="elementor-element elementor-element-d2d9a88 e-con-full e-flex e-con e-parent" data-id="d2d9a88" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-4960f9a e-con-full e-flex e-con e-parent" data-id="4960f9a" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
