				<div class="elementor-element elementor-element-bb0a74c elementor-widget elementor-widget-jet-ajax-search" data-id="bb0a74c" data-element_type="widget" data-settings="{&quot;results_area_columns&quot;:1}" data-widget_type="jet-ajax-search.default">
